// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    address fakeLog;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
        fakeLog = address(new FakeLog());
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0); // actor is an EOA, so in M Log points at an empty account
        amount = bound(amount, 1, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.SetLogFile(fakeLog);
        address depositor = makeAddr("depositor");
        vm.deal(depositor, amount);
        vm.prank(depositor);
        try c.Deposit{value: amount}() {
            assertTrue(true);
        } catch {
            assertTrue(false);
        }
    }
}

contract FakeLog {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
